"""Données du jeu : constantes, chemins et chargement de cartes.json."""
import json
import os
from collections import Counter


ROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
SAVE_DIR = os.path.join(ROOT, 'sauvegardes')
AUTO = os.path.join(SAVE_DIR, '_auto.json')


VERSION = 3


RES = {'B': 'Bois', 'P': 'Pierre', 'A': 'Argile', 'M': 'Minerai',
       'V': 'Verre', 'Y': 'Papyrus', 'T': 'Tissu'}


IDX = 'BPAMVYT'


COL = {'brown': '#8B5A2B', 'grey': '#b0b5ba', 'blue': '#3b6fd4', 'yellow': '#e6c229',
       'red': '#d64545', 'green': '#3fa34d', 'purple': '#8e44ad'}


COLNAME = {'brown': 'Matières premières', 'grey': 'Manufacturés', 'blue': 'Civils',
           'yellow': 'Commerce', 'red': 'Militaires', 'green': 'Scientifiques', 'purple': 'Guildes'}


EXTRA = {'wonder': "étape(s) de merveille", 'defeat': "jeton(s) défaite"}


SCI = {'C': 'Compas', 'R': 'Roue', 'T': 'Tablette'}


CARDS, GUILDS, CITIES = {}, [], {}


def load_data():
    with open(os.path.join(ROOT, 'cartes.json'), encoding='utf-8') as f:
        d = json.load(f)
    for c in d['cards']:
        CARDS[c['name']] = dict(name=c['name'], color=c['color'], cost=c['cost'], eff=tuple(c['eff']),
                                free=tuple(c['free']), copies={int(a): v for a, v in c['copies'].items()})
        if c['color'] == 'purple':
            GUILDS.append(c['name'])
    for name, v in d['cities'].items():
        CITIES[name] = (v['res'], {s: [(cost, [tuple(e) for e in effs]) for cost, effs in v[s]] for s in 'AB'})


def cost_parse(s):
    return s.count('$'), Counter(c for c in s if c in RES)


load_data()

