"""Règles pures : commerce, coûts, chaînages, points. Aucune dépendance à l'interface."""
import itertools
from collections import Counter
from sevenwonders.data import CARDS, CITIES, IDX, cost_parse


def nb(G, i):
    n = len(G['players'])
    return (i + 1) % n, (i - 1) % n


def real(G):
    """Indices des vrais joueurs (sans la Cité franche)."""
    return [i for i, p in enumerate(G['players']) if not p.get('franche')]


def stages(p):
    return CITIES[p['city']][1][p['side']]


def effects(p):
    out = [(CARDS[n]['color'], CARDS[n]['eff']) for n in p['built']]
    for _, effs in stages(p)[:p['stage']]:
        out += [('wonder', e) for e in effs]
    return out


def sell_res(p):
    """Ce qu'un voisin peut m'acheter : ressource de départ + cartes marron/grises (pas jaunes, pas merveille)."""
    f, o = Counter(CITIES[p['city']][0]), []
    for n in p['built']:
        c = CARDS[n]
        if c['color'] in ('brown', 'grey'):
            if c['eff'][0] == 'prod':
                f.update(c['eff'][1])
            elif c['eff'][0] == 'opt':
                o.append(c['eff'][1])
    return f, o


def own_res(p):
    fixed, opts = Counter(CITIES[p['city']][0]), []
    for _, e in effects(p):
        if e[0] == 'prod':
            fixed.update(e[1])
        elif e[0] == 'opt':
            opts.append(e[1])
    return fixed, opts


def trade_disc(p):
    d = {'L': set(), 'R': set()}
    for _, e in effects(p):
        if e[0] == 'trade':
            for s in e[1]:
                d[s] |= set(e[2])
    return d


def prune(plans):
    out = []
    for a in sorted(plans):
        if not any(b[1] <= a[1] for b in out):
            out.append(a)
    return out


def pay_options(G, i, need):
    """Toutes les façons (non dominées) d'acheter les ressources manquantes : liste de (à gauche, à droite)."""
    p = G['players'][i]
    fixed, opts = own_res(p)
    units = [k for k, v in need.items() for _ in range(max(0, v - fixed[k]))]
    if not units:
        return [(0, 0)]
    l, r = nb(G, i)
    side = (sell_res(G['players'][l]), sell_res(G['players'][r]))
    d = trade_disc(p)
    z = (0,) * 7
    st = {(frozenset(), (frozenset(), frozenset()), (z, z)): {(0, 0)}}
    for x in units:
        xi, nxt = IDX.index(x), {}

        def put(key, plans):
            nxt.setdefault(key, set()).update(plans)
        for (uo, uopt, fus), plans in st.items():
            for j, o in enumerate(opts):
                if j not in uo and x in o:
                    put((uo | {j}, uopt, fus), plans)
            for si, s in enumerate('LR'):
                f, o = side[si]
                price = 1 if x in d[s] else 2
                np_ = {(a + price, b) if si == 0 else (a, b + price) for a, b in plans}
                if fus[si][xi] < f[x]:
                    nf, t = list(fus), fus[si]
                    nf[si] = t[:xi] + (t[xi] + 1,) + t[xi + 1:]
                    put((uo, uopt, tuple(nf)), np_)
                for j, oo in enumerate(o):
                    if j not in uopt[si] and x in oo:
                        nu = list(uopt)
                        nu[si] = uopt[si] | {j}
                        put((uo, tuple(nu), fus), np_)
        st = {k: set(prune(v)) for k, v in nxt.items()}
        if not st:
            return []
    return prune(set().union(*st.values()))


def check(G, i, cost, chain=()):
    """None si impossible, sinon liste de plans (banque, gauche, droite).
    Les pièces comptées sont celles du début du tour (résolution simultanée)."""
    p = G['players'][i]
    if any(c in p['built'] for c in chain):
        return [(0, 0, 0)]
    coins, need = cost_parse(cost)
    if coins > p['coins']:
        return None
    plans = [(coins, a, b) for a, b in pay_options(G, i, need) if coins + a + b <= p['coins']]
    return plans or None


def cheap(plans):
    return min(plans, key=sum)


def can_build(G, i, name):
    if name in G['players'][i]['built']:
        return None
    c = CARDS[name]
    return check(G, i, c['cost'], c['free'])


def chain_free(G, i, name):
    p = G['players'][i]
    return name not in p['built'] and any(c in p['built'] for c in CARDS[name]['free'])


def can_wonder(G, i):
    p = G['players'][i]
    if p['stage'] >= len(stages(p)):
        return None
    return check(G, i, stages(p)[p['stage']][0])


def free_avail(G, i):
    p = G['players'][i]
    return any(e[0] == 'free' for _, e in effects(p)) and p['free_age'] != G['age']


def can_free(G, i, name):
    return [(0, 0, 0)] if free_avail(G, i) and name not in G['players'][i]['built'] else None


def has_last(p):
    return any(e[0] == 'last' for _, e in effects(p))


def controller(G, i):
    """Siège du joueur humain qui décide pour la cité i (sa cité, ou la Cité franche s'il a la carte), sinon None (IA)."""
    p = G['players'][i]
    if p.get('franche'):
        return G['holder'] if G['players'][G['holder']]['human'] else None
    return i if p['human'] else None


def human_ctrl(G, i):
    """Un humain décide-t-il pour la cité i ?"""
    return controller(G, i) is not None


def pay(G, i, plan):
    l, r = nb(G, i)
    G['players'][i]['coins'] -= sum(plan)
    G['players'][l]['coins'] += plan[1]
    G['players'][r]['coins'] += plan[2]


def count(G, i, colors, scope):
    l, r = nb(G, i)
    ps = [G['players'][j] for j in {'s': [i], 'sn': [i, l, r], 'n': [l, r]}[scope]]
    if colors == 'wonder':
        return sum(p['stage'] for p in ps)
    if colors == 'defeat':
        return sum(p['defeats'] for p in ps)
    cols = colors.split(',')
    return sum(1 for p in ps for n in p['built'] if CARDS[n]['color'] in cols)


def shields(p):
    return sum(e[1] for _, e in effects(p) if e[0] == 'mil')


def mil_points(p):
    return p['tok'] - p['defeats']


def sci_score(c, r, t):
    return c * c + r * r + t * t + 7 * min(c, r, t)


def sci_total(sym, wild):
    return max(sci_score(sym['C'] + a.count('C'), sym['R'] + a.count('R'), sym['T'] + a.count('T'))
               for a in itertools.product('CRT', repeat=wild))


def score(G, i):
    p = G['players'][i]
    d, sym, wild, copy = Counter(), Counter(), 0, False
    for col, e in effects(p):
        if e[0] == 'pv':
            d['Merveille' if col == 'wonder' else 'Civil'] += e[1]
        elif e[0] == 'cnt':
            d['Guildes' if col == 'purple' else 'Commerce'] += e[4] * count(G, i, e[1], e[2])
        elif e[0] == 'sci':
            if e[1] == '*':
                wild += 1
            else:
                sym[e[1]] += 1
        elif e[0] == 'copyguild':
            copy = True
    if copy:  # Olympie B : copie la meilleure guilde des voisins
        best = 0
        for j in nb(G, i):
            for n in G['players'][j]['built']:
                c = CARDS[n]
                if c['color'] == 'purple':
                    e = c['eff']
                    best = max(best, e[4] * count(G, i, e[1], e[2]) if e[0] == 'cnt'
                               else sci_total(sym, wild + 1) - sci_total(sym, wild))
        d['Guildes'] += best
    d['Science'] = sci_total(sym, wild)
    d['Militaire'] = mil_points(p)
    d['Pièces'] = p['coins'] // 3
    d['Total'] = sum(d.values())
    return d


def ranking(G):
    """Classement final : total, puis nombre de pièces en cas d'égalité."""
    return sorted(((score(G, i), G['players'][i]['city'], G['players'][i]['coins']) for i in real(G)),
                  key=lambda r: (-r[0]['Total'], -r[2]))

