"""Intelligence artificielle : trois niveaux (facile, normal, difficile)."""
import math
import random
from collections import Counter
from sevenwonders.data import CARDS
from sevenwonders.rules import (
    can_build, can_free, can_wonder, chain_free, cheap, count, effects, free_avail, nb, own_res,
    sci_total, score, sell_res, shields, stages, trade_disc)


def ai_easy(G, i, hand, franche=False):
    p = G['players'][i]
    best, bv, bact, bplans = None, -99, 'build', None
    fa = free_avail(G, i)
    for n in set(hand):
        plans, act = can_build(G, i, n), 'build'
        if plans is None and fa and n not in p['built']:
            plans, act = can_free(G, i, n), 'free'
        if plans is None:
            continue
        e = CARDS[n]['eff']
        v = random.random()
        if e[0] == 'pv': v += e[1] * 1.2
        elif e[0] == 'mil': v += e[1] * 2.2
        elif e[0] in ('prod', 'opt'): v += (4 if G['age'] < 3 else .5) + .5 * len(e[1])
        elif e[0] == 'sci': v += 4
        elif e[0] == 'coin': v += 2
        else: v += 2.5
        c = cheap(plans)
        v += 1.5 if sum(c) == 0 else -.4 * sum(c)
        if franche and chain_free(G, i, n):
            v += 100  # Cité franche : le chaînage gratuit est obligatoire
        if v > bv:
            best, bv, bact, bplans = n, v, act, plans
    if best and (franche or random.random() > .12):
        return best, bact, cheap(bplans)
    pw = can_wonder(G, i)
    pool = [n for n in hand if not (franche and chain_free(G, i, n))] or list(hand)
    if pw and (franche or random.random() < .6):
        return random.choice(pool), 'wonder', cheap(pw)
    return random.choice(pool), 'discard', None


CF = {1: .45, 2: .40, 3: .34}


STRATS = ['science', 'guerre', 'civil', 'commerce', 'équilibre']


STRAT = {'science': {'green': 1.35}, 'guerre': {'red': 1.4}, 'civil': {'blue': 1.25},
         'commerce': {'yellow': 1.3, 'brown': 1.1, 'grey': 1.1}}


SUCC = {}


for _n, _c in CARDS.items():
    for _p in _c['free']:
        SUCC.setdefault(_p, []).append(_n)


def _pw(a, b):
    return 1 / (1 + math.exp(-1.3 * (a - b)))


def mil_delta(G, i, add):
    """Gain espéré en points de victoire si j'ajoute `add` boucliers, face à la force actuelle et future des voisins."""
    ps, age = G['players'], G['age']
    s, r, tot = shields(ps[i]), max(0, 7 - G['turn']), 0
    for a in range(age, 4):
        v, w = {1: 1, 2: 3, 3: 5}[a], (1.0 if a == age else .55)
        grow = .15 * (r if a == age else 6) * a
        for j in nb(G, i):
            n = shields(ps[j]) + grow
            f = lambda x: _pw(x + grow * .8, n) * (v + 1) - 1
            tot += w * (f(s + add) - f(s))
    return tot


def res_value(G, i, letters, opt=False):
    p = G['players'][i]
    fixed, opts = own_res(p)
    sell = [sell_res(G['players'][j])[0] for j in nb(G, i)]
    base = {1: 2.0, 2: 1.2, 3: .3}[G['age']]

    def one(ch, k=0):
        have = fixed[ch] + k + .5 * sum(ch in o for o in opts)
        sc = 1.3 if have < .5 else .7 if have < 1.5 else .3
        near = sum(1 for x in sell if x[ch])
        return base * sc * (1, .8, .65)[near] * (1.15 if ch in 'VYT' else 1)
    if opt:
        return .8 * max(one(ch) for ch in letters)
    seen, tot = Counter(), 0
    for ch in letters:
        tot += one(ch, seen[ch])
        seen[ch] += 1
    return tot


def sci_value(G, i, letter):
    sym, wild = Counter(), 0
    for _, e in effects(G['players'][i]):
        if e[0] == 'sci':
            if e[1] == '*': wild += 1
            else: sym[e[1]] += 1
    before = sci_total(sym, wild)
    if letter == '*':
        after = sci_total(sym, wild + 1)
    else:
        s2 = Counter(sym)
        s2[letter] += 1
        after = sci_total(s2, wild)
    spec = {1: 2.2, 2: 1.4, 3: 0}[G['age']] * (1.2 if letter != '*' and sym[letter] == 0 else .9)
    return after - before + spec


def eff_value(G, i, e, cname=None):
    k, age, p = e[0], G['age'], G['players'][i]
    cf = CF[age]
    if k == 'pv': return e[1]
    if k == 'mil': return mil_delta(G, i, e[1]) + .2 * e[1]
    if k in ('prod', 'opt'): return res_value(G, i, e[1], k == 'opt')
    if k == 'sci': return sci_value(G, i, e[1])
    if k == 'coin': return e[1] * cf * (1.1 if age == 1 else 1)
    if k == 'trade':
        fixed, d, tot = own_res(p)[0], trade_disc(p), .3
        for sd in e[1]:
            sell = sell_res(G['players'][nb(G, i)[0 if sd == 'L' else 1]])[0]
            tot += sum({1: 1.3, 2: .9, 3: .3}[age] for ch in e[2] if ch not in d[sd] and fixed[ch] == 0 and sell[ch])
        return tot
    if k == 'cnt':
        n = count(G, i, e[1], e[2])
        itself = 1 if (cname and e[2] != 'n' and CARDS[cname]['color'] in e[1].split(',')) else 0
        return e[3] * (n - itself) * cf + e[4] * (n + (.8 if age < 3 else .4))
    return {'recup': 3.2, 'free': 2.5 * (4 - age), 'last': 2.5, 'copyguild': 3.5}[k]


def benefit(G, i, name, lvl):
    """Ce que rapporte la carte une fois posée (avant de payer son coût)."""
    c, p = CARDS[name], G['players'][i]
    v = eff_value(G, i, c['eff'], name)
    if lvl == 2:
        v *= STRAT.get(p.get('strat'), {}).get(c['color'], 1)
    if G['age'] < 3:
        v += .6 * sum(1 for x in SUCC.get(name, ()) if x not in p['built'])  # chaînages à venir
    return v


def pick_plan(G, i, plans, lvl):
    if lvl < 2 or len(plans) == 1:
        return cheap(plans)
    l, r = nb(G, i)
    tl, tr = score(G, l)['Total'], score(G, r)['Total']
    m = (tl + tr) / 2
    wl, wr = 1 + .02 * (tl - m), 1 + .02 * (tr - m)  # on préfère enrichir le voisin le moins dangereux
    return min(plans, key=lambda pl: pl[0] + pl[1] * wl + pl[2] * wr)


def pick_recup(G, i, names):
    lvl = G['players'][i].get('lvl', G.get('level', 1))
    if lvl == 0:
        return random.choice(names)
    return max(names, key=lambda n: benefit(G, i, n, lvl))


def ai_smart(G, i, hand, franche=False):
    p, age, turn = G['players'][i], G['age'], G['turn']
    lvl = p.get('lvl', G.get('level', 1))
    noise, cf, fa = (0, .9, .25)[lvl], CF[age], free_avail(G, i)
    ben = {n: benefit(G, i, n, lvl) for n in set(hand)}
    opts = []  # (valeur, carte, action, plan)
    for n in ben:
        plans = can_build(G, i, n)
        forced = 100 if (franche and chain_free(G, i, n)) else 0
        if plans:
            pl = pick_plan(G, i, plans, lvl)
            opts.append((ben[n] - cf * sum(pl) + forced, n, 'build', pl))
        if fa and n not in p['built']:  # pouvoir d'Olympie : on le garde pour plus tard sauf si ça rapporte gros
            opts.append((ben[n] - max(0, 2.5 - .5 * (turn - 1)) + forced, n, 'free', (0, 0, 0)))
    best_build = max(opts, key=lambda o: o[0]) if opts else None

    def waste(n):  # ce qu'on perd (et ce qu'on offre au voisin) en sacrifiant la carte n
        w = .3 * max(0, ben[n])
        if lvl == 2 and not G['two']:
            j = (i + (-1 if age == 2 else 1)) % len(G['players'])
            w += .3 * max(0, benefit(G, j, n, 1))
        return w
    cards = sorted(ben, key=waste)
    sac = next((n for n in cards if not (best_build and n == best_build[1])), cards[0])
    if franche:
        free_cards = [n for n in cards if not chain_free(G, i, n)]
        sac = free_cards[0] if free_cards else sac
    pw = can_wonder(G, i)
    if pw:
        sv = sum(eff_value(G, i, e) for e in stages(p)[p['stage']][1]) + .4
        opts.append((sv - cf * sum(cheap(pw)) - waste(sac), sac, 'wonder', pick_plan(G, i, pw, lvl)))
    if not franche or not opts:
        opts.append((3 * cf - waste(sac) - (1.5 if turn == 6 else 0), sac, 'discard', None))
    top = max(opts, key=lambda o: o[0] + (random.gauss(0, noise) if noise else 0))
    return top[1], top[2], top[3]


def ai_choose(G, i, hand, franche=False):
    lvl = G['players'][i].get('lvl', G.get('level', 1))
    return (ai_easy if lvl == 0 else ai_smart)(G, i, hand, franche)

