"""Déroulement de la partie : tours simultanés, âges, conflits, variante 2 joueurs."""
import random
from sevenwonders.ai import STRATS, ai_choose, pick_recup
from sevenwonders.data import CARDS, CITIES, GUILDS, VERSION
from sevenwonders.rules import count, has_last, human_ctrl, nb, pay, real, shields, stages


def gain(G, i, e, cname=None):
    p = G['players'][i]
    if e[0] == 'coin':
        p['coins'] += e[1]
    elif e[0] == 'cnt':
        k = count(G, i, e[1], e[2])
        if cname and e[2] != 'n' and CARDS[cname]['color'] in e[1].split(','):
            k -= 1  # la carte qui vient d'être posée ne compte pas dans son propre gain en pièces (Phare)
        p['coins'] += e[3] * k
    elif e[0] == 'recup':
        G['recups'].append(i)


def label(G, i):
    p = G['players'][i]
    if p.get('franche'):
        return f"Cité franche ({p['city']})"
    return p.get('name') or ("Vous" if i == 0 and not G.get('demo') else p['city'])


def recup_build(G, i, name):
    p = G['players'][i]
    G['discard'].remove(name)
    p['built'].append(name)
    G['log'].append(f"{label(G, i)} : reprend {name} dans la défausse")
    gain(G, i, CARDS[name]['eff'], name)


def settle_recups(G):
    todo, G['recups'] = G['recups'], []
    for i in todo:
        ok = sorted({n for n in G['discard'] if n not in G['players'][i]['built']})
        if ok:
            if human_ctrl(G, i):
                G['pending'].append(i)
            else:
                recup_build(G, i, pick_recup(G, i, ok))


def apply_actions(G, acts, final=False):
    ps = G['players']
    G['recups'] = []
    for i, name, act, plan, src in acts:  # 1. cartes retirées des mains, paiements (état du début de tour)
        (G['pile'] if src == 'pile' else ps[src]['hand']).remove(name)
        if act != 'discard':
            pay(G, i, plan)
    for i, name, act, plan, src in acts:  # 2. mise en jeu simultanée
        p = ps[i]
        if act in ('build', 'free'):
            p['built'].append(name)
            if act == 'free':
                p['free_age'] = G['age']
            txt = f"construit {name}" + (" gratuitement (pouvoir)" if act == 'free' else "")
        elif act == 'wonder':
            p['stage'] += 1
            txt = f"construit l'étape {p['stage']} de sa merveille"
        else:
            p['coins'] += 3
            G['discard'].append(name)
            txt = "défausse une carte (+3 pièces)"
        G['log'].append(f"{label(G, i)} : {txt}")
    if final:  # 6e tour : la carte restante est défaussée (sans pièces), avant le choix d'Halicarnasse
        for i in real(G):
            if ps[i]['hand'] and not has_last(ps[i]):
                G['discard'] += ps[i]['hand']
                ps[i]['hand'] = []
        if G['two']:
            G['discard'] += G['pile']
            G['pile'] = []
    for i, name, act, plan, src in acts:  # 3. gains (comptent les cartes posées ce tour par les voisins)
        if act in ('build', 'free'):
            gain(G, i, CARDS[name]['eff'], name)
        elif act == 'wonder':
            for e in stages(ps[i])[ps[i]['stage'] - 1][1]:
                gain(G, i, e)
    settle_recups(G)


def make_deck(age, n):
    guilds = random.sample(GUILDS, min(n + 2, len(GUILDS))) if age == 3 else []
    cards = [nm for nm, c in CARDS.items() for t in c['copies'].get(age, []) if t <= n]
    want = 7 * n - len(guilds)
    random.shuffle(cards)
    while len(cards) < want:
        cards.append(random.choice(cards))
    cards = cards[:want] + guilds
    random.shuffle(cards)
    return cards


def begin_turn(G):
    if G['two']:  # variante 2 joueurs : celui qui a la carte Cité franche pioche
        G['players'][G['holder']]['hand'].append(G['pile'].pop(0))


def start_age(G):
    deck = make_deck(G['age'], 3 if G['two'] else len(real(G)))
    for k, i in enumerate(real(G)):
        G['players'][i]['hand'] = deck[7 * k:7 * k + 7]
    if G['two']:
        G['pile'] = deck[14:21]
        G['holder'] = 1 if G['age'] == 2 else 0
    G['turn'] = 1
    G['log'].append(f"=== ÂGE {G['age']} ===")
    begin_turn(G)


def new_game(n, city=None, side=None, level=1, seats=None):
    """Nouvelle partie. `seats` (facultatif) décrit chaque joueur : {'name', 'human', 'city', 'side'}.
    Sans `seats` : le joueur 0 est humain et les autres sont des IA (comportement historique)."""
    if seats:
        n = len(seats)
    two = n == 2
    total = 3 if two else n  # variante 2 joueurs : la Cité franche est une 3e cité
    wanted = ([s.get('city') for s in seats] if seats else [city]) + [None] * total
    pool = [c for c in CITIES if c not in wanted]
    random.shuffle(pool)
    cities, used = [], set()
    for k in range(total):
        c = wanted[k]
        cities.append(c if c in CITIES and c not in used else pool.pop())
        used.add(cities[-1])
    sides = [s.get('side') for s in seats] if seats else [side]
    G = {'v': VERSION, 'age': 1, 'turn': 1, 'discard': [], 'over': False, 'log': [], 'pending': [], 'recups': [],
         'extra': False, 'extra_seats': [], 'two': two, 'holder': 0, 'pile': [], 'level': level,
         'players': [dict(city=c, name=(seats[k].get('name') if seats and k < len(seats) else None),
                          side=sides[k] if k < len(sides) and sides[k] in ('A', 'B') else random.choice('AB'), coins=3,
                          built=[], stage=0, tok=0, defeats=0, hand=[],
                          human=(seats[k].get('human', False) if seats and k < len(seats) else (k == 0 and not seats)),
                          free_age=0, franche=(two and k == 2), strat=random.choice(STRATS))
                     for k, c in enumerate(cities)]}
    start_age(G)
    return G


def military(G):
    val = {1: 1, 2: 3, 3: 5}[G['age']]
    sh = [shields(p) for p in G['players']]
    rows = []
    for i, p in enumerate(G['players']):
        res = []
        for j in nb(G, i):
            if sh[i] > sh[j]:
                p['tok'] += val
                res.append([G['players'][j]['city'], sh[j], 'V', val])
            elif sh[i] < sh[j]:
                p['defeats'] += 1
                res.append([G['players'][j]['city'], sh[j], 'D', -1])
            else:
                res.append([G['players'][j]['city'], sh[j], '=', 0])
        rows.append(dict(i=i, city=p['city'], shields=sh[i], res=res))
    G['conflict'], G['conflict_new'] = dict(age=G['age'], rows=rows), True
    G['log'].append(f"— Conflits de l'âge {G['age']} (boucliers : {', '.join(map(str, sh))}) —")


def rotate(G):
    ps = G['players']
    if G['two']:  # les joueurs échangent les paquets de chaque côté de la frontière
        ps[0]['hand'], ps[1]['hand'] = ps[1]['hand'], ps[0]['hand']
        G['holder'] = 1 - G['holder']
        return
    n, dr = len(ps), (-1 if G['age'] == 2 else 1)  # âges I et III : vers la gauche, âge II : vers la droite
    hands = [p['hand'] for p in ps]
    for i in range(n):
        ps[(i + dr) % n]['hand'] = hands[i]


def close_age(G):
    for p in G['players']:
        G['discard'] += p['hand']
        p['hand'] = []
    G['pile'] = []
    military(G)
    if G['age'] == 3:
        G['over'] = True
    else:
        G['age'] += 1
        start_age(G)


def end_turn(G):
    if G['turn'] < 6:
        rotate(G)
        G['turn'] += 1
        begin_turn(G)
        G['log'] = G['log'][-300:]
        return None
    waiting = []
    for i in real(G):  # Babylone B : la 7e carte est jouée au lieu d'être défaussée
        p = G['players'][i]
        if p['hand']:
            if p['human']:
                waiting.append(i)
            else:
                name, act, plan = ai_choose(G, i, p['hand'])
                apply_actions(G, [(i, name, act, plan, i)])
    if waiting:
        G['extra'], G['extra_seats'] = True, waiting
        G['log'].append("Pouvoir de Babylone : " + ", ".join(label(G, i) for i in waiting) + " joue(nt) aussi la 7e carte.")
        return 'extra'
    close_age(G)


def advance(G):
    if G['pending']:
        return 'recup'
    if G['extra']:
        if G.get('extra_seats', [0]):
            return 'extra'
        G['extra'] = False
        close_age(G)
        return None
    return end_turn(G)


def play_turn(G, hacts):
    """hacts : toutes les actions des joueurs humains (une par humain, deux pour celui qui a la carte Cité franche).
    Les IA jouent, tout est résolu en même temps."""
    acts = list(hacts)
    done = {a[0] for a in acts}
    for i in real(G):
        if i not in done:
            name, act, plan = ai_choose(G, i, G['players'][i]['hand'])
            acts.append((i, name, act, plan, i))
    if G['two'] and 2 not in done:  # l'IA a la carte Cité franche : elle joue aussi pour elle
        h = G['holder']
        rest = list(G['players'][h]['hand'])
        rest.remove([a for a in acts if a[0] == h][0][1])
        name, act, plan = ai_choose(G, 2, rest, True)
        acts.append((2, name, act, plan, h))
    apply_actions(G, acts, final=(G['turn'] == 6))
    return advance(G)


human_turn = play_turn  # nom historique (partie à un seul humain)


def extra_play(G, seat, act, plan):
    """Babylone B : le joueur `seat` joue sa 7e carte."""
    name = G['players'][seat]['hand'][0]
    apply_actions(G, [(seat, name, act, plan, seat)])
    G['extra_seats'] = [s for s in G.get('extra_seats', [seat]) if s != seat]
    return advance(G)


def human_extra(G, act, plan):
    return extra_play(G, 0, act, plan)


def finish_recup(G, name):
    i = G['pending'].pop(0)
    if name:
        recup_build(G, i, name)
    return advance(G)

sevenwonders/session.py:
"""Parties à plusieurs joueurs humains (avec ou sans IA) — indépendant de l'interface ET du réseau.

Principe : un « hôte » garde l'état complet de la partie G (un simple dict JSON) et :
  • envoie à chaque joueur `view_for(G, siège)` (son état, sans les mains des autres) ;
  • reçoit leurs choix et les passe à `submit_turn` / `submit_recup` / `submit_extra` ;
  • demande à `options_for(G, siège)` ce que le joueur a le droit de faire (l'interface n'a donc aucune règle à connaître).
Quand tous les humains ont joué, le tour est résolu (les IA jouent en même temps) et la partie avance.
"""
import copy

from sevenwonders.ai import ai_choose, pick_recup
from sevenwonders.game import extra_play, finish_recup, new_game, play_turn
from sevenwonders.rules import can_build, can_free, can_wonder, chain_free, cheap, controller, real


class SessionError(ValueError):
    """Choix refusé (pas le bon moment, carte absente de la main, paiement invalide...)."""


# ---------------------------------------------------------------- création et état
def new_session(seats, level=1):
    """seats : liste de {'name': str, 'human': bool, 'city': facultatif, 'side': facultatif}, 2 à 7 sièges."""
    if not 2 <= len(seats) <= 7:
        raise SessionError("une partie compte de 2 à 7 joueurs")
    G = new_game(len(seats), level=level, seats=seats)
    G['inbox'] = {}  # choix déjà reçus ce tour : {siège (texte): actions}
    _pump(G)
    return G


def phase(G):
    if G['over']:
        return 'over'
    if G['pending']:
        return 'recup'
    if G['extra']:
        return 'extra'
    return 'choose'


def waiting(G):
    """Sièges dont on attend une décision maintenant."""
    ph = phase(G)
    if ph == 'choose':
        return [i for i in real(G) if G['players'][i]['human'] and str(i) not in G['inbox']]
    if ph == 'recup':
        c = controller(G, G['pending'][0])
        return [] if c is None else [c]
    if ph == 'extra':
        return [s for s in G['extra_seats'] if G['players'][s]['human']]
    return []


def status(G):
    return {'phase': phase(G), 'waiting': waiting(G), 'age': G['age'], 'turn': G['turn'], 'over': G['over']}


def _pump(G):
    """Fait avancer la partie tant qu'aucun humain n'a de décision à prendre (IA, joueurs remplacés...)."""
    for _ in range(500):
        ph = phase(G)
        if ph == 'over':
            return
        if ph == 'choose':
            if waiting(G):
                return
            acts = [(a[0], a[1], a[2], tuple(a[3]) if a[3] is not None else None, a[4])
                    for lst in G['inbox'].values() for a in lst]
            G['inbox'] = {}
            play_turn(G, acts)
        elif ph == 'recup':
            i = G['pending'][0]
            if controller(G, i) is not None:
                return
            ok = sorted({n for n in G['discard'] if n not in G['players'][i]['built']})
            finish_recup(G, pick_recup(G, i, ok) if ok else None)
        else:  # extra
            for s in list(G['extra_seats']):
                if not G['players'][s]['human']:
                    _, act, plan = ai_choose(G, s, G['players'][s]['hand'])
                    extra_play(G, s, act, plan)
            if waiting(G):
                return


# ---------------------------------------------------------------- ce que chaque joueur peut faire
def _franche(G, ci):
    return bool(G['players'][ci].get('franche'))  # la 3e cité de la variante 2 joueurs (et elle seule)


def _card_options(G, ci, name):
    pb, pw, pf = can_build(G, ci, name), can_wonder(G, ci), can_free(G, ci, name)
    forced = _franche(G, ci) and chain_free(G, ci, name)  # Cité franche : chaînage gratuit obligatoire
    return {'city': ci, 'name': name, 'build': pb, 'wonder': None if forced else pw, 'free': None if forced else pf,
            'discard': not forced and (not _franche(G, ci) or (pb is None and pw is None and pf is None)), 'forced': forced}


def options_for(G, seat):
    """Tout ce que `seat` peut jouer maintenant. Les paiements sont des listes [banque, gauche, droite]."""
    ph = phase(G)
    p = G['players'][seat]
    out = {'phase': ph, 'seat': seat, 'waiting': seat in waiting(G), 'cards': [], 'recup': []}
    if out['waiting'] and ph in ('choose', 'extra'):
        cities = [seat] + ([2] if ph == 'choose' and G['two'] and G['holder'] == seat else [])
        for ci in cities:
            for name in sorted(set(p['hand'])):
                out['cards'].append(_card_options(G, ci, name))
        out['plays'] = len(cities)  # nombre de cartes à jouer (2 si on a la carte Cité franche)
    if out['waiting'] and ph == 'recup':
        i = G['pending'][0]
        out['recup_city'] = i
        out['recup'] = sorted({n for n in G['discard'] if n not in G['players'][i]['built']})
    return out


def view_for(G, seat):
    """L'état de la partie tel que le joueur `seat` a le droit de le voir (mains des autres cachées)."""
    V = copy.deepcopy(G)
    for i, p in enumerate(V['players']):
        p['hand_n'] = len(p['hand'])
        if i != seat:
            p['hand'] = []
        if not G['over']:
            p.pop('strat', None)  # le style de jeu des IA est secret
    V['pile_n'], V['pile'] = len(G['pile']), []
    V['discard_n'] = len(G['discard'])
    if not G['over']:
        V['discard'] = []  # les cartes défaussées sont face cachée
    V['submitted'] = sorted(int(k) for k in G['inbox'])
    V['inbox'] = {}
    V.update(you=seat, phase=phase(G), waiting=waiting(G))
    return V


# ---------------------------------------------------------------- validation et soumission des choix
def check_action(G, ci, name, act, plan):
    """Vérifie un choix et renvoie le plan de paiement à appliquer (ou lève SessionError)."""
    forced = _franche(G, ci) and chain_free(G, ci, name)
    if act == 'discard':
        if forced:
            raise SessionError("la Cité franche doit prendre le chaînage gratuit")
        if _franche(G, ci) and any(x is not None for x in (can_build(G, ci, name), can_wonder(G, ci), can_free(G, ci, name))):
            raise SessionError("la Cité franche ne peut défausser que si elle ne peut rien construire")
        return None
    plans = {'build': can_build, 'wonder': lambda G, c, n: can_wonder(G, c), 'free': can_free}.get(act)
    plans = plans(G, ci, name) if plans else None
    if plans is None:
        raise SessionError(f"« {name} » : action impossible ({act})")
    if forced and act != 'build':
        raise SessionError("la Cité franche doit prendre le chaînage gratuit")
    if plan is None:
        return cheap(plans)
    if tuple(plan) not in {tuple(x) for x in plans}:
        raise SessionError("paiement invalide")
    return tuple(plan)


def _norm(seat, a):
    if isinstance(a, dict):
        ci, name, act, plan = a['city'], a['name'], a['act'], a.get('plan')
    else:
        ci, name, act, plan = a[:4]
    return int(ci), name, act, (tuple(plan) if plan is not None else None), seat


def validate_turn(G, seat, acts):
    holds_franche = G['two'] and G['holder'] == seat
    acts = [_norm(seat, a) for a in acts]
    if sorted(a[0] for a in acts) != sorted([seat] + ([2] if holds_franche else [])):
        raise SessionError("il faut jouer une carte pour chaque cité dont vous avez la charge")
    hand, out = list(G['players'][seat]['hand']), []
    for ci, name, act, plan, src in acts:
        if name not in hand:
            raise SessionError(f"« {name} » n'est pas dans votre main")
        hand.remove(name)
        out.append((ci, name, act, check_action(G, ci, name, act, plan), src))
    return out


def _state(G):
    _pump(G)
    return status(G)


def submit_turn(G, seat, acts):
    """Le joueur `seat` choisit sa (ou ses deux) carte(s). Quand tous les humains ont joué, le tour est résolu."""
    if phase(G) != 'choose':
        raise SessionError("ce n'est pas le moment de choisir une carte")
    if seat not in waiting(G):
        raise SessionError("ce joueur a déjà joué (ou n'est pas un joueur humain)")
    G['inbox'][str(seat)] = [list(a) for a in validate_turn(G, seat, acts)]
    return _state(G)


def submit_recup(G, seat, name):
    """Halicarnasse : choix d'une carte de la défausse (None pour renoncer)."""
    if phase(G) != 'recup' or seat not in waiting(G):
        raise SessionError("ce n'est pas à vous de choisir dans la défausse")
    i = G['pending'][0]
    if name is not None and name not in {n for n in G['discard'] if n not in G['players'][i]['built']}:
        raise SessionError("carte indisponible dans la défausse")
    finish_recup(G, name)
    return _state(G)


def submit_extra(G, seat, act, plan=None):
    """Babylone B : jouer la 7e carte."""
    if phase(G) != 'extra' or seat not in waiting(G):
        raise SessionError("vous ne jouez pas de 7e carte maintenant")
    plan = check_action(G, seat, G['players'][seat]['hand'][0], act, plan)
    extra_play(G, seat, act, plan)
    return _state(G)


# ---------------------------------------------------------------- joueurs absents
def force_ai_move(G, seat):
    """Joue à la place d'un humain (délai dépassé) : l'IA choisit pour lui."""
    if seat not in waiting(G):
        raise SessionError("ce joueur n'a rien à jouer")
    ph, p = phase(G), G['players'][seat]
    if ph == 'choose':
        hand = list(p['hand'])
        name, act, plan = ai_choose(G, seat, hand)
        acts = [{'city': seat, 'name': name, 'act': act, 'plan': plan}]
        if G['two'] and G['holder'] == seat:
            hand.remove(name)
            n2, a2, p2 = ai_choose(G, 2, hand, True)
            acts.append({'city': 2, 'name': n2, 'act': a2, 'plan': p2})
        return submit_turn(G, seat, acts)
    if ph == 'recup':
        i = G['pending'][0]
        ok = sorted({n for n in G['discard'] if n not in G['players'][i]['built']})
        return submit_recup(G, seat, pick_recup(G, i, ok) if ok else None)
    _, act, plan = ai_choose(G, seat, p['hand'])
    return submit_extra(G, seat, act, plan)


def replace_by_ai(G, seat):
    """Un joueur quitte la partie : une IA prend sa place pour de bon (son choix déjà envoyé reste valable)."""
    G['players'][seat]['human'] = False
    G['log'].append(f"{G['players'][seat].get('name') or G['players'][seat]['city']} quitte la partie : une IA prend sa place.")
    return _state(G)

sevenwonders/web.py:
"""Pont Python <-> navigateur (Pyodide) : le moteur tourne chez l'hôte, le JavaScript ne connaît aucune règle.

Toutes les fonctions reçoivent UN texte JSON et renvoient du texte JSON.
Le JavaScript de l'hôte appelle `start`, puis, à chaque message d'un joueur, `submit_*`, puis `pack(siège)` pour
fabriquer ce que ce joueur doit voir (état + coups autorisés).
"""
import json

from sevenwonders import session as S
from sevenwonders.data import CARDS, CITIES, COL, COLNAME, RES
from sevenwonders.rules import mil_points, own_res, real, score, shields, trade_disc
from sevenwonders.texts import RULES, eff_text

_G = None  # la partie en cours (côté hôte uniquement)
SCORE_KEYS = ('Militaire', 'Pièces', 'Merveille', 'Civil', 'Commerce', 'Science', 'Guildes', 'Total')


def _score(G, i):
    d = score(G, i)
    return {k: d.get(k, 0) for k in SCORE_KEYS}


def static(_=None):
    """Données d'affichage (cartes, cités, couleurs, règles) : identiques pour tout le monde."""
    cards = {n: dict(color=c['color'], cost=c['cost'], eff=list(c['eff']), free=list(c['free']), text=eff_text(c['eff']))
             for n, c in CARDS.items()}
    cities = {n: dict(res=v[0], **{s: [dict(cost=cost, eff=[list(e) for e in effs], text=' + '.join(eff_text(e) for e in effs))
                                        for cost, effs in v[1][s]] for s in 'AB'}) for n, v in CITIES.items()}
    return json.dumps(dict(cards=cards, cities=cities, colors=COL, colorNames=COLNAME, res=RES, rules=RULES))


def start(arg):
    """arg = {'seats': [{'name', 'human', 'city'?, 'side'?}...], 'level': 0|1|2}"""
    global _G
    cfg = json.loads(arg)
    _G = S.new_session(cfg['seats'], cfg.get('level', 1))
    return json.dumps({'ok': True})


def _do(fn, *args):
    try:
        fn(_G, *args)
        return json.dumps({'ok': True})
    except S.SessionError as e:
        return json.dumps({'error': str(e)})


def submit_turn(arg):
    a = json.loads(arg)
    return _do(S.submit_turn, a['seat'], a['acts'])


def submit_recup(arg):
    a = json.loads(arg)
    return _do(S.submit_recup, a['seat'], a.get('name'))


def submit_extra(arg):
    a = json.loads(arg)
    return _do(S.submit_extra, a['seat'], a['act'], a.get('plan'))


def force_ai(arg):
    """L'IA joue à la place d'un joueur absent ou trop lent."""
    return _do(S.force_ai_move, json.loads(arg)['seat'])


def replace_ai(arg):
    """Un joueur a quitté la partie : une IA prend sa place."""
    return _do(S.replace_by_ai, json.loads(arg)['seat'])


def _extra(G, i):
    p = G['players'][i]
    fixed, opts = own_res(p)
    d = trade_disc(p)
    return dict(shields=shields(p), mil=mil_points(p), prod=''.join(k * v for k, v in fixed.items()), opts=list(opts),
                trade=dict(L=''.join(sorted(d['L'])), R=''.join(sorted(d['R']))),
                score=None if p.get('franche') else _score(G, i))


def pack(arg):
    """Ce que le joueur `seat` doit voir : état (sans les mains des autres), coups autorisés, classement final."""
    seat = json.loads(arg)['seat']
    G = _G
    V = S.view_for(G, seat)
    V['extras'] = [_extra(G, i) for i in range(len(G['players']))]
    out = {'view': V, 'options': S.options_for(G, seat)}
    if G['over']:
        rows = [dict(seat=i, name=G['players'][i].get('name') or G['players'][i]['city'], city=G['players'][i]['city'],
                     coins=G['players'][i]['coins'], score=_score(G, i)) for i in real(G)]
        out['ranking'] = sorted(rows, key=lambda r: (-r['score']['Total'], -r['coins']))
    return json.dumps(out)


def export_state(_=None):
    return json.dumps(_G)


def import_state(arg):
    global _G
    _G = json.loads(arg)
    return json.dumps({'ok': True})
